/* Minimalistisches Lightbox-Skript als Ersatz */
(function() {
    window.GLightbox = function(options) {
        var selector = options.selector || '.glightbox';
        var elements = document.querySelectorAll(selector);

        // Container erstellen, falls nicht vorhanden
        var container = document.createElement('div');
        container.className = 'glightbox-container';
        container.innerHTML = '<button class="gclose"></button><div class="gslider"><div class="gslide"><img></div></div>';
        document.body.appendChild(container);

        var img = container.querySelector('img');
        var closeBtn = container.querySelector('.gclose');

        elements.forEach(function(el) {
            el.addEventListener('click', function(e) {
                e.preventDefault();
                img.src = el.getAttribute('href');
                container.style.display = 'block';
                setTimeout(function() { container.style.opacity = '1'; }, 10);
            });
        });

        closeBtn.addEventListener('click', function() {
            container.style.opacity = '0';
            setTimeout(function() { container.style.display = 'none'; }, 250);
        });
    };
})();
